    }
  ],
  "sample_video_script_15s": {
    "scene_1": "Close-up: baby stretching and smiling. VO: 'Comfort shouldn’t crinkle.'",
    "scene_2": "Cut to hands pressing on quilted liner. Super: 'FeatherSoft + AirFlow'",
    "scene_3": "Parent lifts baby—no red marks around legs. Super: 'StretchFit comfort'",
    "scene_4": "Overnight time-lapse with sleeping baby. Super: 'Up to 12 hours dry'",
